const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'The Power of Vaccination'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Right accent block
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 0, w: 3.0, h: 5.625,
    fill: { color: theme.secondary, transparency: 40 }
  });

  // Gold accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 2.65, w: 1.8, h: 0.05,
    fill: { color: theme.accent }
  });

  // Title
  slide.addText("The Power of\nVaccination", {
    x: 0.6, y: 0.7, w: 6.0, h: 2.0,
    fontSize: 46, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", valign: "bottom",
    lineSpacingMultiple: 1.05
  });

  // Subtitle
  slide.addText("From Smallpox Eradication to COVID-19\nin Record Time", {
    x: 0.6, y: 2.85, w: 6.0, h: 0.85,
    fontSize: 20, fontFace: "Calibri",
    color: theme.accent
  });

  // Scope badge
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.95, w: 1.8, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("1796 – 2020", {
    x: 0.6, y: 3.95, w: 1.8, h: 0.4,
    fontSize: 15, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });

  // Source attribution
  slide.addText("Source: Our World in Data  |  ourworldindata.org/vaccination", {
    x: 0.6, y: 5.0, w: 5.5, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary
  });

  // Decorative circles on right block
  slide.addShape(pres.shapes.OVAL, {
    x: 8.0, y: 1.5, w: 1.2, h: 1.2,
    fill: { color: theme.accent, transparency: 75 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 7.5, y: 3.2, w: 0.8, h: 0.8,
    fill: { color: theme.light, transparency: 70 }
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

