const slideConfig = {
  type: 'content',
  subtype: 'comparison',
  index: 3,
  title: '100% Case Reduction Achieved for Diphtheria, Polio, and Smallpox in the US'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0,
    fit: "shrink"
  });

  // Subtitle
  slide.addText("Pre-vaccine vs. post-vaccine annual case and death rates per million population  |  Source: Roush & Murphy (2007)", {
    x: 0.5, y: 0.75, w: 9, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary
  });

  // Table
  const mkHdr = () => ({ fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 9, fontFace: "Calibri", align: "center", valign: "middle" });
  const mkHdrLeft = () => ({ fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 9, fontFace: "Calibri", align: "left", valign: "middle" });

  // 100% elimination rows get gold accent on the percentage
  const mkCell = () => ({ fill: { color: "FFFFFF" }, color: theme.primary, fontSize: 9, fontFace: "Calibri", align: "center", valign: "middle", border: { pt: 0.5, color: theme.secondary } });
  const mkCellAccent = () => ({ fill: { color: "FFFFFF" }, color: theme.accent, fontSize: 9, fontFace: "Calibri", bold: true, align: "center", valign: "middle", border: { pt: 0.5, color: theme.secondary } });
  const mkName = () => ({ fill: { color: "FFFFFF" }, color: theme.primary, fontSize: 9, fontFace: "Calibri", bold: true, align: "left", valign: "middle", border: { pt: 0.5, color: theme.secondary } });
  const mkNameElim = () => ({ fill: { color: theme.secondary, transparency: 85 }, color: theme.primary, fontSize: 9, fontFace: "Calibri", bold: true, align: "left", valign: "middle", border: { pt: 0.5, color: theme.secondary } });
  const mkCellElim = () => ({ fill: { color: theme.secondary, transparency: 85 }, color: theme.primary, fontSize: 9, fontFace: "Calibri", align: "center", valign: "middle", border: { pt: 0.5, color: theme.secondary } });
  const mkCellElimAccent = () => ({ fill: { color: theme.secondary, transparency: 85 }, color: theme.accent, fontSize: 9, fontFace: "Calibri", bold: true, align: "center", valign: "middle", border: { pt: 0.5, color: theme.secondary } });

  const tableData = [
    // Header
    [
      { text: "Disease", options: mkHdrLeft() },
      { text: "Pre-Vaccine\nCases/million/yr", options: mkHdr() },
      { text: "Post-Vaccine\nCases/million/yr", options: mkHdr() },
      { text: "Case\nReduction", options: mkHdr() },
      { text: "Pre-Vaccine\nDeaths/million/yr", options: mkHdr() },
      { text: "Death\nReduction", options: mkHdr() }
    ],
    // 100% elimination rows (highlighted)
    [
      { text: "Diphtheria", options: mkNameElim() },
      { text: "158", options: mkCellElim() },
      { text: "0", options: mkCellElim() },
      { text: "100%", options: mkCellElimAccent() },
      { text: "13.7", options: mkCellElim() },
      { text: "100%", options: mkCellElimAccent() }
    ],
    [
      { text: "Smallpox", options: mkNameElim() },
      { text: "250", options: mkCellElim() },
      { text: "0", options: mkCellElim() },
      { text: "100%", options: mkCellElimAccent() },
      { text: "2.9", options: mkCellElim() },
      { text: "100%", options: mkCellElimAccent() }
    ],
    [
      { text: "Acute polio", options: mkNameElim() },
      { text: "141", options: mkCellElim() },
      { text: "0", options: mkCellElim() },
      { text: "100%", options: mkCellElimAccent() },
      { text: "10", options: mkCellElim() },
      { text: "100%", options: mkCellElimAccent() }
    ],
    // Near-elimination rows
    [
      { text: "Measles", options: mkName() },
      { text: "3,044", options: mkCell() },
      { text: "0.2", options: mkCell() },
      { text: "99.99%", options: mkCellAccent() },
      { text: "2.5", options: mkCell() },
      { text: "100%", options: mkCellAccent() }
    ],
    [
      { text: "Rubella", options: mkName() },
      { text: "242", options: mkCell() },
      { text: "0.04", options: mkCell() },
      { text: "99.98%", options: mkCellAccent() },
      { text: "0.09", options: mkCell() },
      { text: "100%", options: mkCellAccent() }
    ],
    [
      { text: "Pertussis", options: mkName() },
      { text: "1,534", options: mkCell() },
      { text: "52", options: mkCell() },
      { text: "96.6%", options: mkCell() },
      { text: "30.8", options: mkCell() },
      { text: "99.7%", options: mkCell() }
    ],
    // Incomplete reduction rows
    [
      { text: "Hepatitis A", options: mkName() },
      { text: "465", options: mkCell() },
      { text: "51", options: mkCell() },
      { text: "89%", options: mkCell() },
      { text: "0.5", options: mkCell() },
      { text: "88.7%", options: mkCell() }
    ],
    [
      { text: "Acute hepatitis B", options: mkName() },
      { text: "273", options: mkCell() },
      { text: "44", options: mkCell() },
      { text: "83.9%", options: mkCell() },
      { text: "1", options: mkCell() },
      { text: "83.6%", options: mkCell() }
    ],
    [
      { text: "Pneumococcal", options: mkName() },
      { text: "233", options: mkCell() },
      { text: "139", options: mkCell() },
      { text: "40.5%", options: mkCell() },
      { text: "24", options: mkCell() },
      { text: "31.3%", options: mkCell() }
    ]
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.1, w: 9.0,
    colW: [1.6, 1.5, 1.5, 1.2, 1.5, 1.2],
    rowH: [0.4, 0.35, 0.35, 0.35, 0.35, 0.35, 0.35, 0.35, 0.35, 0.35],
    border: { pt: 0.5, color: theme.secondary }
  });

  // Legend note at bottom
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.75, w: 0.15, h: 0.15,
    fill: { color: theme.secondary, transparency: 85 }
  });
  slide.addText("= 100% elimination of both cases and deaths", {
    x: 0.75, y: 4.73, w: 3.5, h: 0.2,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

