const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'data-visualization',
  index: 4,
  title: 'Measles Cases Collapsed Across All 50 US States After Vaccine Mandates'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0,
    fit: "shrink"
  });

  // Heatmap image
  slide.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.3, y: 0.95, w: 6.2, h: 4.2,
    sizing: { type: "contain", w: 6.2, h: 4.2 }
  });

  // Milestone annotations on right side
  const milestones = [
    { year: "1963", desc: "First measles vaccine\ndeveloped by John Enders", y: 1.1 },
    { year: "1971", desc: "MMR vaccine developed\nby Maurice Hilleman", y: 2.35 },
    { year: "1980", desc: "Vaccination became\nmandatory for kindergarten", y: 3.6 }
  ];

  milestones.forEach(m => {
    // Year badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.8, y: m.y, w: 0.85, h: 0.38,
      fill: { color: theme.accent },
      rectRadius: 0.03
    });
    slide.addText(m.year, {
      x: 6.8, y: m.y, w: 0.85, h: 0.38,
      fontSize: 14, fontFace: "Georgia",
      color: theme.primary, bold: true, align: "center", valign: "middle"
    });
    // Description
    slide.addText(m.desc, {
      x: 7.8, y: m.y - 0.05, w: 1.9, h: 0.55,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary
    });
    // Connecting line
    slide.addShape(pres.shapes.LINE, {
      x: 6.35, y: m.y + 0.19, w: 0.45, h: 0,
      line: { color: theme.accent, width: 1.5, dashType: "dash" }
    });
  });

  // Key stat callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 4.4, w: 2.9, h: 0.6,
    fill: { color: theme.primary }
  });
  slide.addText("Before 1963: 100–1,000+ cases per 100,000 per state  |  After 1980: Near zero", {
    x: 6.9, y: 4.4, w: 2.7, h: 0.6,
    fontSize: 9, fontFace: "Calibri",
    color: "FFFFFF", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

