const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'timeline',
  index: 5,
  title: 'Smallpox: The Only Human Disease Eradicated Through Vaccination'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0,
    fit: "shrink"
  });

  // Subtitle
  slide.addText("From WHO resolution to global certification in just 21 years", {
    x: 0.5, y: 0.75, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: theme.secondary
  });

  // Timeline horizontal line
  slide.addShape(pres.shapes.LINE, {
    x: 0.8, y: 2.15, w: 8.4, h: 0,
    line: { color: theme.secondary, width: 2 }
  });

  // Timeline events
  const events = [
    { year: "1959", label: "WHO Resolution", desc: "World Health Assembly\npasses resolution to\neradicate smallpox", x: 0.8 },
    { year: "1967", label: "Intensified Campaign", desc: "WHO launches\nintensified global\neradication effort", x: 3.3 },
    { year: "1977", label: "Last Natural Case", desc: "Last natural case\nrecorded in Somalia\n(Ali Maow Maalin)", x: 5.8 },
    { year: "1980", label: "Certified Eradicated", desc: "WHO declares\nsmallpox eradicated\nworldwide", x: 8.3 }
  ];

  events.forEach(e => {
    // Circle marker on timeline
    slide.addShape(pres.shapes.OVAL, {
      x: e.x + 0.35, y: 1.97, w: 0.35, h: 0.35,
      fill: { color: theme.accent }
    });
    // Year above
    slide.addText(e.year, {
      x: e.x, y: 1.35, w: 1.05, h: 0.45,
      fontSize: 20, fontFace: "Georgia",
      color: theme.primary, bold: true, align: "center"
    });
    // Label
    slide.addText(e.label, {
      x: e.x, y: 1.8, w: 1.05, h: 0.2,
      fontSize: 9, fontFace: "Calibri",
      color: theme.secondary, bold: true, align: "center"
    });
    // Description below timeline
    slide.addText(e.desc, {
      x: e.x - 0.15, y: 2.5, w: 1.35, h: 0.7,
      fontSize: 9, fontFace: "Calibri",
      color: theme.primary, align: "center"
    });
  });

  // Key factors section
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.5, w: 9.0, h: 0.03,
    fill: { color: theme.accent }
  });

  slide.addText("Why Smallpox Was Uniquely Suited for Eradication", {
    x: 0.5, y: 3.65, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  const factors = [
    { num: "01", text: "The virus infected only humans — no animal reservoir to sustain transmission" },
    { num: "02", text: "Symptoms were easily distinguishable — enabling rapid identification and containment" },
    { num: "03", text: "The vaccine was cheap, stable, and effective — feasible for mass global distribution" }
  ];

  factors.forEach((f, i) => {
    const fy = 4.15 + i * 0.45;
    // Number badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: fy, w: 0.35, h: 0.25,
      fill: { color: theme.primary }
    });
    slide.addText(f.num, {
      x: 0.7, y: fy, w: 0.35, h: 0.25,
      fontSize: 9, fontFace: "Calibri",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });
    // Text
    slide.addText(f.text, {
      x: 1.2, y: fy - 0.02, w: 8.0, h: 0.3,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary
    });
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

