const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'mixed-media',
  index: 6,
  title: 'Herd Immunity: How Vaccinating Many Protects the Most Vulnerable'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0,
    fit: "shrink"
  });

  // === DIAGRAM: Grid of people (left side) ===
  const gridSize = 0.32;
  const gap = 0.07;
  const startX = 0.8;
  const startY = 1.3;
  const rows = 6;
  const cols = 7;

  // Vulnerable positions (cluster in center)
  const vulnerableSet = new Set([
    "2,2", "2,3", "2,4",
    "3,2", "3,3", "3,4",
    "4,2", "4,3", "4,4"
  ]);

  // Shield shape around vulnerable cluster
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: startX + 1.5 * (gridSize + gap) - 0.12,
    y: startY + 1.5 * (gridSize + gap) - 0.12,
    w: 4 * (gridSize + gap) + 0.24,
    h: 4 * (gridSize + gap) + 0.24,
    fill: { color: theme.accent, transparency: 85 },
    line: { color: theme.accent, width: 1.5, dashType: "dash" },
    rectRadius: 0.1
  });

  // "Shield" label
  slide.addText("Protection\nzone", {
    x: startX + 2 * (gridSize + gap),
    y: startY + 1.5 * (gridSize + gap) - 0.35,
    w: 1.5, h: 0.35,
    fontSize: 8, fontFace: "Calibri",
    color: theme.accent, bold: true, align: "center"
  });

  // Draw grid of circles
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const isVulnerable = vulnerableSet.has(`${row},${col}`);
      slide.addShape(pres.shapes.OVAL, {
        x: startX + col * (gridSize + gap),
        y: startY + row * (gridSize + gap),
        w: gridSize, h: gridSize,
        fill: { color: isVulnerable ? theme.light : theme.secondary }
      });
    }
  }

  // Legend
  slide.addShape(pres.shapes.OVAL, {
    x: 0.8, y: 4.05, w: 0.18, h: 0.18,
    fill: { color: theme.secondary }
  });
  slide.addText("Vaccinated individual", {
    x: 1.05, y: 4.02, w: 1.6, h: 0.22,
    fontSize: 9, fontFace: "Calibri",
    color: theme.primary, valign: "middle"
  });

  slide.addShape(pres.shapes.OVAL, {
    x: 2.8, y: 4.05, w: 0.18, h: 0.18,
    fill: { color: theme.light }
  });
  slide.addText("Vulnerable individual", {
    x: 3.05, y: 4.02, w: 1.6, h: 0.22,
    fontSize: 9, fontFace: "Calibri",
    color: theme.primary, valign: "middle"
  });

  // === EXPLANATION (right side) ===
  slide.addText("How Herd Immunity Works", {
    x: 5.0, y: 1.2, w: 4.5, h: 0.35,
    fontSize: 16, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  slide.addText("When enough people are vaccinated, pathogens cannot spread effectively through a population. This creates a protective barrier that shields those who cannot be vaccinated.", {
    x: 5.0, y: 1.65, w: 4.5, h: 0.7,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary
  });

  slide.addText("Who relies on herd immunity:", {
    x: 5.0, y: 2.5, w: 4.5, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, bold: true
  });

  const groups = [
    { label: "Newborns", desc: "Too young to receive vaccinations" },
    { label: "Immunocompromised", desc: "Weakened immune systems cannot mount response" },
    { label: "Chemotherapy patients", desc: "Cancer treatments suppress immunity" }
  ];

  groups.forEach((g, i) => {
    const gy = 2.95 + i * 0.65;
    // Accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.0, y: gy, w: 0.06, h: 0.45,
      fill: { color: theme.light }
    });
    slide.addText(g.label, {
      x: 5.2, y: gy - 0.02, w: 4.2, h: 0.25,
      fontSize: 12, fontFace: "Calibri",
      color: theme.primary, bold: true
    });
    slide.addText(g.desc, {
      x: 5.2, y: gy + 0.2, w: 4.2, h: 0.22,
      fontSize: 10, fontFace: "Calibri",
      color: theme.secondary
    });
  });

  // Key stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.0, y: 4.55, w: 4.5, h: 0.5,
    fill: { color: theme.primary }
  });
  slide.addText("Vaccines protect not just individuals — they protect entire communities.", {
    x: 5.15, y: 4.55, w: 4.2, h: 0.5,
    fontSize: 11, fontFace: "Calibri",
    color: theme.accent, bold: true, valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

