const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'data-visualization',
  index: 7,
  title: 'Gaps Persist: Pneumococcal Disease Shows Only 40% Case Reduction'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0,
    fit: "shrink"
  });

  // Subtitle
  slide.addText("Diseases with incomplete vaccine impact in the US", {
    x: 0.5, y: 0.75, w: 9, h: 0.25,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary
  });

  // Grouped bar chart: Case reduction vs Death reduction
  slide.addChart(pres.charts.BAR, [
    {
      name: "Case Reduction",
      labels: ["Pneumococcal", "Hepatitis A", "Acute Hepatitis B"],
      values: [40.5, 89, 83.9]
    },
    {
      name: "Death Reduction",
      labels: ["Pneumococcal", "Hepatitis A", "Acute Hepatitis B"],
      values: [31.3, 88.7, 83.6]
    }
  ], {
    x: 0.4, y: 1.1, w: 5.0, h: 3.5,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [theme.secondary, theme.accent],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 9,
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 9,
    valAxisMaxVal: 100,
    valAxisLabelColor: theme.primary,
    valAxisLabelFontSize: 9,
    valGridLine: { style: "none" },
    catGridLine: { style: "none" },
    showLegend: true,
    legendPos: "b",
    legendColor: theme.primary,
    legendFontSize: 9,
    showTitle: false,
    chartArea: { fill: { color: "FFFFFF" } }
  });

  // 100% reference line label
  slide.addText("100% = full elimination", {
    x: 0.5, y: 4.65, w: 3, h: 0.2,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, italic: true
  });

  // Barriers section on right
  slide.addText("Key Barriers to Full Coverage", {
    x: 5.7, y: 1.1, w: 3.8, h: 0.35,
    fontSize: 15, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  const barriers = [
    { title: "Access Gaps", desc: "Globally, not everyone has access to vaccines — supply chains and infrastructure remain inadequate in many regions" },
    { title: "Supply Shortages", desc: "Vaccine supply disruptions put children at risk, particularly in low-income countries" },
    { title: "Trust Challenges", desc: "Poor scientific understanding and misinformation reduce vaccine confidence and uptake" }
  ];

  barriers.forEach((b, i) => {
    const by = 1.6 + i * 1.05;
    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.7, y: by, w: 3.8, h: 0.9,
      fill: { color: theme.primary }
    });
    // Accent bar on left
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.7, y: by, w: 0.06, h: 0.9,
      fill: { color: theme.accent }
    });
    // Title
    slide.addText(b.title, {
      x: 5.9, y: by + 0.05, w: 3.4, h: 0.25,
      fontSize: 12, fontFace: "Georgia",
      color: theme.accent, bold: true
    });
    // Description
    slide.addText(b.desc, {
      x: 5.9, y: by + 0.3, w: 3.4, h: 0.55,
      fontSize: 9, fontFace: "Calibri",
      color: "FFFFFF"
    });
  });

  // Source
  slide.addText("Source: Roush & Murphy (2007), Our World in Data", {
    x: 0.5, y: 4.9, w: 5, h: 0.2,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

