const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways: Vaccines Have Eliminated Deadly Diseases — But the Job Isn\'t Done'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.3, w: 9, h: 0.55,
    fontSize: 32, fontFace: "Georgia",
    color: "FFFFFF", bold: true
  });

  // Subtitle
  slide.addText("Vaccines Have Eliminated Deadly Diseases — But the Job Isn't Done", {
    x: 0.5, y: 0.8, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: theme.accent
  });

  // Key findings
  const findings = [
    "Vaccines achieved 100% elimination of cases and deaths for diphtheria, smallpox, and polio in the US",
    "Development timelines collapsed from over 100 years (typhoid) to under 1 year (COVID-19), driven by mRNA technology and genomic tools",
    "Measles cases dropped to near zero across all 50 US states following the 1980 kindergarten vaccination mandate",
    "Smallpox remains the only human disease eradicated through vaccination, certified in 1980 after a global campaign",
    "Gaps persist for pneumococcal disease (40.5% case reduction), hepatitis A (89%), and hepatitis B (83.9%)"
  ];

  findings.forEach((f, i) => {
    const fy = 1.35 + i * 0.52;
    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.6, y: fy, w: 0.25, h: 0.25,
      fill: { color: theme.accent }
    });
    slide.addText(String(i + 1), {
      x: 0.6, y: fy, w: 0.25, h: 0.25,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary, bold: true, align: "center", valign: "middle"
    });
    // Finding text
    slide.addText(f, {
      x: 1.0, y: fy - 0.02, w: 8.5, h: 0.35,
      fontSize: 12, fontFace: "Calibri",
      color: "FFFFFF"
    });
  });

  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.0, w: 9.0, h: 0.03,
    fill: { color: theme.accent }
  });

  // Call to action box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.2, w: 9.0, h: 0.85,
    fill: { color: theme.accent },
    rectRadius: 0.05
  });

  slide.addText("Call to Action", {
    x: 0.7, y: 4.22, w: 8.6, h: 0.3,
    fontSize: 14, fontFace: "Georgia",
    color: theme.primary, bold: true
  });

  slide.addText("Improve access, expand coverage, and strengthen trust in vaccination — global health systems must commit to closing the remaining gaps.", {
    x: 0.7, y: 4.52, w: 8.6, h: 0.45,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

